svg.script:
{
  "diagramType": "Clean Architecture",
  "projectName": "Food Delivery System",
  "description": "Concentric circles: entities, use cases, interface adapters, frameworks",
  "layers": [
    {
      "layer": "Enterprise Business Rules",
      "depth": 1,
      "position": {"x": 960, "y": 540},
      "radius": 100,
      "components": ["Entities", "Domain Objects"]
    },
    {
      "layer": "Use Cases",
      "depth": 2,
      "position": {"x": 960, "y": 540},
      "radius": 200,
      "components": ["Application Use Cases", "Business Logic"]
    },
    {
      "layer": "Interface Adapters",
      "depth": 3,
      "position": {"x": 960, "y": 540},
      "radius": 300,
      "components": ["Controllers", "Gateways", "Presenters", "Repositories"]
    },
    {
      "layer": "Frameworks & Tools",
      "depth": 4,
      "position": {"x": 960, "y": 540},
      "radius": 400,
      "components": ["Web", "Database", "UI", "External Interfaces"]
    }
  ],
  "designTokens": {"lightMode": {"canvas": "#FFFFFF"}, "darkMode": {"canvas": "#0D0D0D"}}
}
